import {bindPrimaryCurrency,selectedProperty,selectedVariant,rateFields,priceFields,readRates,readPrices} from './currency-ui.js';
const $=s=>document.querySelector(s);
// Header height changes with viewport and language; never cover the first content row.
const headerObserver=new ResizeObserver(entries=>document.documentElement.style.setProperty('--header-height',`${entries[0].target.getBoundingClientRect().height}px`));
headerObserver.observe($('.header'));
let preferredCurrency='USD';try{localStorage.removeItem('viicasa-currency');}catch{}
let lang='es';try{lang=localStorage.getItem('viicasa-prototype-language')==='en'?'en':'es';}catch{}
const L=(es,en)=>lang==='es'?es:en;
const regionLabel=region=>region==='canada'?L('Canadá','Canada'):region==='rest_of_world'?L('Resto del mundo','Rest of the world'):L('No detectado','Not detected');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const translated=v=>{const p=String(v||'').split('\n[EN]\n');return lang==='en'?(p[1]||p[0]):p[0];};
const bilingual=v=>{const p=String(v||'').split(' / ');return lang==='en'?(p[1]||p[0]):p[0];};
const money=(n,c='USD')=>n===null?L('Tarifa no disponible','Rate unavailable'): new Intl.NumberFormat(lang==='es'?'es-MX':'en-US',{style:'currency',currency:c,currencyDisplay:'narrowSymbol',minimumFractionDigits:2,maximumFractionDigits:2}).format(n/100)+' '+c;
const icons={home:'M3 10 12 3l9 7M5 9v12h14V9M9 21v-8h6v8',bed:'M3 18v3m18-3v3M3 18V7h18v11H3m0-5h18M6 7v6m6-6v6',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8',bath:'M3 12h18M5 12V5a2 2 0 0 1 4 0m-6 7v4a5 5 0 0 0 5 5h8a5 5 0 0 0 5-5v-4M7 21v2m10-2v2',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0M12 13a3 3 0 1 0 0-6 3 3 0 0 0 0 6',wifi:'M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0M8 16a6 6 0 0 1 8 0M12 20h.01',sun:'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',check:'m5 12 4 4L19 6',arrow:'M4 12h16m-6-6 6 6-6 6',calendar:'M5 5h14v16H5zM8 2v6m8-6v6M5 11h14',bag:'M4 7h16l-1 14H5L4 7m4 0V5a4 4 0 0 1 8 0v2',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z'};
const icon=n=>`<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.home}"/></svg>`;
let settings={demo:false,googleEnabled:false,commerceEnabled:false},currentProperties=[],currentProducts=[];
async function api(path,options={}){const response=await fetch('/api'+path,{...options,headers:{...(options.body&&!(options.body instanceof FormData)?{'Content-Type':'application/json'}:{}),...options.headers},body:options.body instanceof FormData?options.body:options.body?JSON.stringify(options.body):undefined});const result=response.status===204?{}:await response.json();if(!response.ok)throw Object.assign(new Error(result.error||L('No se pudo completar la operación','Unable to complete the operation')),{status:response.status});return result;}
const imageUrl=url=>typeof url==='string'&&(/^(\/assets\/|\/v1\/media\/)/.test(url)||/^https:\/\//.test(url))?url:'';
const demoImages={'casa-brisa':['interior.png','bedroom.png','exterior.png'],'villa-oliva':['exterior.png','life.png','bedroom.png'],'casa-lumbre':['life.png','interior.png','bedroom.png'],'residencia-arena':['interior.png','exterior.png','bedroom.png'],'jarron-terra':['objects.png','shop.png'],'lino-natural':['bedroom.png','shop.png'],'ritual-casa':['shop.png','objects.png']};
const photos=p=>(p.images||[]).map(imageUrl).filter(Boolean).length?(p.images||[]).map(imageUrl).filter(Boolean):settings.demo?(demoImages[p.slug]||[]).map(i=>'/assets/'+i):[];
const photo=(p,cls='')=>photos(p).length?`<img class="${cls}" src="${esc(photos(p)[0])}" alt="${esc(bilingual(p.name))}" loading="lazy">`:`<div class="no-photo">${icon('home')}${L('Imagen pendiente','Image pending')}</div>`;
function banner(){return settings.demo?`<div class="demo-banner">${L('ENTORNO DE DEMOSTRACIÓN · Propiedades, precios y productos ficticios. Sin cobros reales.','DEMONSTRATION ENVIRONMENT · Fictional properties, prices and products. No real charges.')}</div>`:'';}
function navigation(){
  $('.wordmark').href='/';$('#navigation').innerHTML=`<a href="/propiedades" ${location.pathname.startsWith('/propiedades')||location.pathname.startsWith('/viiconcierge/')?'aria-current="page"':''}>${L('Propiedades','Properties')}</a><a href="/shop">ViiShop</a><a href="/viiconcierge">ViiConcierge</a><a href="/viilife">ViiLife</a>`;
  $('#account').textContent=L('Mi cuenta','My account');$('#account').onclick=()=>location.href='/cuenta';
  document.querySelectorAll('[data-language]').forEach(b=>{b.setAttribute('aria-pressed',b.dataset.language===lang);b.onclick=()=>{try{localStorage.setItem('viicasa-prototype-language',b.dataset.language);}catch{}location.reload();};});
  document.documentElement.lang=lang;
  $('#navigation').ariaLabel=L('Navegación principal','Main navigation');$('#feed').ariaLabel=L('Contenido principal','Main content');$('.skip').textContent=L('Ir al contenido','Skip to content');
}
function frame(content){document.body.classList.add('platform');navigation();$('#feed').innerHTML=banner()+content+`<section class="site-footer"><a class="footer-wordmark" href="/">VIICASA</a><p>${L('El arte de habitar.','The art of being home.')}</p><div><a href="/cuenta">${L('Mi cuenta','My account')}</a><a href="/admin">${L('Administración','Administration')}</a><a href="/privacidad">${L('Privacidad y condiciones','Privacy & terms')}</a></div><small>© ${new Date().getFullYear()} VIICASA</small></section>`;$('#feed').scrollTop=0;}
function busy(){frame(`<section class="loading"><span class="loader"></span>${L('Preparando tu experiencia…','Preparing your experience…')}</section>`);}
function failure(error){frame(`<section class="empty"><p class="kicker">VIICASA</p><h1>${L('Un momento, por favor.','One moment, please.')}</h1><p>${esc(error.message)}</p><button class="btn" onclick="location.reload()">${L('Reintentar','Try again')}</button></section>`);}
function modal(title,content){const d=$('#detail');$('#detail-content').innerHTML=`<h2>${esc(title)}</h2>${content}`;d.setAttribute('aria-label',title);$('#close').ariaLabel=L('Cerrar','Close');$('#close').onclick=()=>d.close();d.showModal();return d;}
const note=()=>`<p class="quiet">${L('Consulta las condiciones antes de continuar.','Please review the terms before continuing.')}</p>`;
function notify(text){let e=$('#toast');if(!e){e=document.createElement('div');e.id='toast';e.setAttribute('role','status');document.body.append(e);}e.textContent=text;clearTimeout(notify.timer);notify.timer=setTimeout(()=>e.remove(),6000);}
function statusLabel(v){const all={pending:['Pendiente de pago','Awaiting payment'],confirmed:['Confirmada','Confirmed'],cancelled:['Cancelada','Cancelled'],expired:['Vencida','Expired'],payment_review:['Pago en revisión','Payment under review'],new:['Nueva','New'],attended:['Atendida','Handled'],archived:['Archivada','Archived']};return all[v]?L(...all[v]):v;}
const today=()=>new Date(Date.now()+86400000).toISOString().slice(0,10);
async function allPages(path){let list=[],cursor;do{const p=await api(path+'?limit=100'+(cursor?'&cursor='+encodeURIComponent(cursor):''));list.push(...p.items);cursor=p.next_cursor;}while(cursor&&list.length<500);return list;}
function propertyCard(p,i){return `<article class="property-card"><a class="property-photo" href="/viiconcierge/${esc(p.slug)}">${photo(p)}<span class="image-label">${L('Residencia privada','Private residence')}</span><span class="photo-count">${icon('grid')} ${photos(p).length}</span><span class="image-arrow">↗</span></a><div class="card-heading"><div><p class="location">${icon('pin')}${esc(bilingual(p.location.replace(' · ',' / ')))}</p><h3><a href="/viiconcierge/${esc(p.slug)}">${esc(p.name)}</a></h3></div><span class="catalog-no">0${i+1}</span></div><div class="property-meta"><span>${icon('people')}${p.capacity} ${L('huéspedes','guests')}</span><span>${icon('bed')}${p.bedrooms} ${L('recámaras','bedrooms')}</span><span>${icon('bath')}${p.bathrooms}</span></div><div class="card-bottom"><span><strong>${money(p.nightly_minor,p.currency)}</strong> <small>/ ${L('noche','night')}</small></span><a href="/viiconcierge/${esc(p.slug)}">${L('Descubrir','Discover')} ↗</a></div></article>`;}
async function properties(){
  currentProperties=(await allPages('/properties')).map(p=>selectedProperty(p,preferredCurrency));document.title=L('Propiedades — VIICASA','Properties — VIICASA');
  frame(`<section class="catalog-intro"><div><p class="kicker">VIICASA COLLECTION</p><h1>${L('Lugares para','Places to')}<br><em>${L('sentirte en casa.','feel at home.')}</em></h1><p>${L('Arquitectura, naturaleza y espacios para compartir. Encuentra el lugar para tu próxima estancia.','Architecture, nature and spaces to share. Find the setting for your next stay.')}</p></div><div class="intro-photo"><img src="/assets/exterior.png" alt="${L('Referencia de arquitectura residencial','Residential architecture reference')}"><span>${L('Una estancia. Otra manera de vivir.','One stay. A different way of living.')}</span></div></section><section class="catalog-section"><form class="search-bar" id="search"><label>${icon('pin')}<span>${L('Destino o propiedad','Destination or property')}<input name="q" placeholder="${L('¿Dónde quieres estar?','Where would you like to be?')}"></span></label><label>${icon('people')}<span>${L('Huéspedes','Guests')}<select name="guests"><option value="0">${L('Cualquier capacidad','Any capacity')}</option>${[2,4,6,8,10].map(n=>`<option>${n}</option>`).join('')}</select></span></label><label><span>${L('Ordenar por','Sort by')}<select name="sort"><option value="featured">${L('Nuestra selección','Our selection')}</option><option value="asc">${L('Menor precio','Lowest price')}</option><option value="desc">${L('Mayor precio','Highest price')}</option></select></span></label><button class="btn">${L('Explorar','Explore')} ${icon('arrow')}</button></form><div class="catalog-toolbar"><div class="chips" id="chips"><button class="chip active" data-type="">${L('Todas','All')}</button>${['Costa','Bosque','Ciudad'].map((x,i)=>`<button class="chip" data-type="${x}">${L(x,['Coast','Forest','City'][i])}</button>`).join('')}</div><span id="result-count" role="status"></span></div><div class="property-grid" id="property-grid"></div><div class="editorial-strip"><span>ViiConcierge</span><h2>${L('Tu estancia comienza<br>con los detalles.','Your stay begins<br>with the details.')}</h2><p>${L('Consulta fechas, revisa las amenidades y conoce las condiciones de cada residencia antes de reservar.','Check dates, explore amenities and review the terms of each residence before booking.')}</p></div></section>`);
  let type='';const update=()=>{const f=new FormData($('#search')),q=String(f.get('q')).toLowerCase(),g=Number(f.get('guests'));let items=currentProperties.filter(p=>(p.name+' '+p.location).toLowerCase().includes(q)&&p.capacity>=g&&(!type||p.location.includes(type)));if(f.get('sort')!=='featured')items.sort((a,b)=>Number(b.price_available)-Number(a.price_available)||(a.nightly_minor-b.nightly_minor)*(f.get('sort')==='desc'?-1:1));$('#property-grid').innerHTML=items.length?items.map(propertyCard).join(''):`<div class="empty"><h2>${L('Un lugar por encontrar.','A place yet to be found.')}</h2><p>${L('Prueba otro destino o número de huéspedes.','Try another destination or guest count.')}</p><button class="btn outline" id="reset-filters">${L('Limpiar filtros','Clear filters')}</button></div>`;$('#result-count').textContent=`${items.length} ${L('propiedades','properties')}`;if($('#reset-filters'))$('#reset-filters').onclick=()=>{$('#search').reset();type='';document.querySelectorAll('[data-type]').forEach(b=>b.classList.toggle('active',b.dataset.type===''));update();};};$('#search').onsubmit=e=>{e.preventDefault();update();};document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{type=b.dataset.type;document.querySelectorAll('[data-type]').forEach(x=>x.classList.toggle('active',x===b));update();});update();
}
function gallery(p){const imgs=photos(p);return `<div class="gallery ${imgs.length<2?'single':''}">${imgs.slice(0,3).map((im,i)=>`<button data-gallery="${i}" aria-label="${L('Abrir fotografía','Open photo')} ${i+1}"><img src="${esc(im)}" alt="${esc(p.name)} · ${i+1}">${i===0?`<span class="gallery-caption">${icon('grid')}${L('Ver galería','View gallery')} (${imgs.length})</span>`:''}</button>`).join('')||'<div class="no-photo">'+L('Galería pendiente','Gallery pending')+'</div>'}</div>`;}
function wireGallery(p){document.querySelectorAll('[data-gallery]').forEach(b=>b.onclick=()=>{const imgs=photos(p);let n=Number(b.dataset.gallery);modal(p.name,`<img id="large-photo" class="large-photo" src="${esc(imgs[n])}" alt="${esc(p.name)}"><div class="gallery-controls"><button id="previous-photo" aria-label="${L('Foto anterior','Previous photo')}">←</button><span id="photo-index">${n+1} / ${imgs.length}</span><button id="next-photo" aria-label="${L('Foto siguiente','Next photo')}">→</button></div>`);const change=d=>{n=(n+d+imgs.length)%imgs.length;$('#large-photo').src=imgs[n];$('#photo-index').textContent=`${n+1} / ${imgs.length}`;};$('#previous-photo').onclick=()=>change(-1);$('#next-photo').onclick=()=>change(1);});}
async function property(slug){
  const p=selectedProperty(await api('/properties/'+encodeURIComponent(slug)),preferredCurrency);document.title=p.name+' — VIICASA';
  frame(`<section class="property-detail"><a class="back-link" href="/propiedades">← ${L('Todas las propiedades','All properties')}</a><div class="property-title"><div><p class="kicker">${esc(bilingual(p.location.replace(' · ',' / ')))}</p><h1>${esc(p.name)}</h1></div><span class="tag">${L('Residencia privada','Private residence')}</span></div>${gallery(p)}<div class="detail-columns"><article class="property-story"><div class="detail-stats"><span>${icon('people')}<strong>${p.capacity}</strong>${L('Huéspedes','Guests')}</span><span>${icon('bed')}<strong>${p.bedrooms}</strong>${L('Recámaras','Bedrooms')}</span><span>${icon('bath')}<strong>${p.bathrooms}</strong>${L('Baños','Bathrooms')}</span><span>${icon('calendar')}<strong>${p.min_nights}</strong>${L('Noches mínimas','Minimum nights')}</span></div><p class="kicker">${L('EL ESPACIO','THE SPACE')}</p><h2>${L('Habitar de otra manera.','A different way to stay.')}</h2><p class="prose">${esc(translated(p.description))}</p><h3>${L('Lo que encontrarás','What you will find')}</h3><div class="amenity-grid">${p.amenities.map(a=>`<span>${icon(a.toLowerCase().includes('wi')?'wifi':a.toLowerCase().includes('terra')||a.toLowerCase().includes('jard')?'sun':'check')}${esc(bilingual(a))}</span>`).join('')}</div><div class="policy-block"><h3>${L('Antes de reservar','Before you book')}</h3><p class="prose">${esc(translated(p.policies))}</p><p>${L('La disponibilidad se valida al cotizar y nuevamente al reservar.','Availability is checked when quoting and again when booking.')}</p></div><button class="btn outline" id="property-inquiry">${L('Consultar sobre esta propiedad','Enquire about this property')}</button></article><aside class="booking-box"><p class="kicker">${L('TU PRÓXIMA ESTANCIA','YOUR NEXT STAY')}</p><div class="booking-price">${money(p.nightly_minor,p.currency)}<small>/ ${L('noche','night')}</small></div><form id="quote-form"><div class="form-pair"><label>${L('Llegada','Check-in')}<input type="date" name="check_in" min="${today()}" required></label><label>${L('Salida','Check-out')}<input type="date" name="check_out" min="${today()}" required></label></div><label>${L('Huéspedes','Guests')}<select name="guests">${Array.from({length:p.capacity},(_,i)=>`<option>${i+1}</option>`).join('')}</select></label><button class="btn full" ${!p.price_available?'disabled':''}>${L('Consultar disponibilidad','Check availability')}</button></form><div id="quote-result" aria-live="polite"></div><p class="quiet">${L('No se realizará ningún cobro al consultar.','You will not be charged for checking availability.')}</p></aside></div></section>`);wireGallery(p);$('#property-inquiry').onclick=()=>inquiry(p);
  const form=$('#quote-form');form.oninput=()=>{$('#quote-result').innerHTML='';};form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button');button.disabled=true;const values=Object.fromEntries(new FormData(form));const input={property_id:p.id,currency:preferredCurrency,...values,guests:Number(values.guests)};try{const q=await api('/bookings/quote',{method:'POST',body:input});$('#quote-result').innerHTML=`<p class="availability">${icon('check')}${L('Disponible para tus fechas','Available for your dates')}</p><div class="price-line"><span>${q.nights} ${L('noches','nights')}</span><span>${money(q.nights*q.nightly_minor,q.currency)}</span></div><div class="price-line"><span>${L('Limpieza','Cleaning')}</span><span>${money(q.cleaning_minor,q.currency)}</span></div><div class="price-line total"><span>Total</span><span>${money(q.total_minor,q.currency)}</span></div><button class="btn full" id="reserve" ${!settings.commerceEnabled?'disabled':''}>${L('Continuar con mi reserva','Continue booking')} ↗</button>`;$('#reserve').onclick=()=>{location.href='/checkout?'+new URLSearchParams({...input,kind:'booking'});};}catch(err){$('#quote-result').innerHTML=`<p class="error">${esc(errorText(err))}</p>`;}finally{button.disabled=false;}};
}
function errorText(error){if(lang==='es')return error.message;const map={'La propiedad no está disponible en esas fechas':'The property is unavailable for these dates.','La sesión de visitante expiró':'Your session has expired.','Estancia mínima: 2 noches':'Minimum stay: 2 nights','El carrito está vacío':'Your basket is empty.','No se pudo iniciar la sesión':'Unable to start your session.','Acceso administrativo requerido':'Administrator sign-in is required.','El registro de operaciones todavía no está habilitado':'Bookings and enquiries are not enabled yet.'};return map[error.message]||L(error.message,'Unable to complete this request. Please check your details and try again.');}

async function start(){
  try{
    settings=await api('/config');preferredCurrency=settings.suggestedCurrency||'USD';const path=location.pathname;
    if(['/shop','/viiconcierge','/viilife'].includes(path)){
      await import('/app.js');navigation();
      $('#prototype').textContent=settings.demo?L('Demostración · Sin cobros reales','Demo · No real charges'):'';
      document.querySelectorAll('[data-detail]').forEach(b=>{
        if(path!=='/viilife')b.innerHTML=(path==='/shop'?L('Explorar la colección','Explore the collection'):L('Explorar propiedades','Explore properties'))+' <span aria-hidden="true">↗</span>';
        b.onclick=()=>path==='/viilife'?inquiry(null,L(['Limpieza','Lavado de ropa','Preparación del hogar'][Number(b.dataset.detail)],['Cleaning','Laundry','Home preparation'][Number(b.dataset.detail)])):location.href=path==='/shop'?'/coleccion':'/propiedades';
      });
      return;
    }
    busy();if(path==='/propiedades')await properties();else if(path.startsWith('/viiconcierge/'))await property(path.split('/')[2]);else await otherRoute(path);
  }catch(e){failure(e);}
}
