async function account(){const a=await api('/account');frame(`<section class="page-wrap"><div class="section-title"><div><p class="kicker">VIICASA · ${L('MI CUENTA','MY ACCOUNT')}</p><h1>${a.profile?L('Bienvenido,','Welcome,')+'<br><em>'+esc(a.profile.name)+'.</em>':L('Tu espacio personal.','Your personal space.')}</h1></div>${a.profile?`<button class="btn outline" id="logout">${L('Cerrar sesión','Sign out')}</button>`:`<div class="sign-in-card"><button class="btn" id="google-login" ${!settings.googleEnabled?'disabled':''}>G &nbsp; ${L('Continuar con Google','Continue with Google')}</button><p class="quiet">${settings.googleEnabled?L('Inicia sesión o crea tu cuenta con Google.','Sign in or create your account with Google.'):L('Google estará disponible al conectar el entorno real.','Google will be available when the live environment is connected.')}</p></div>`}</div>${a.profile?`<p class="quiet">${L('Zona al registrarte (estimada por IP)','Registration region (estimated by IP)')}: <span class="tag">${regionLabel(a.profile.registration?.region)}</span></p>`:''}<h3>${L('Reservaciones y pedidos','Bookings & orders')}</h3>${!a.profile?`<p class="quiet">${L('Estas operaciones pertenecen a la sesión de este navegador. Inicia sesión antes de reservar para asociarlas a tu cuenta.','These checkouts belong to this browser session. Sign in before booking to associate them with your account.')}</p>`:''}<div class="activity-list">${a.items.map(c=>`<a href="/checkout?id=${c.id}"><span>${icon(c.kind==='booking'?'home':'bag')}</span><div><strong>${esc(c.detail.property_name||'ViiShop')}</strong><p>${new Date(c.created_at).toLocaleDateString(lang==='es'?'es-MX':'en-US')} · ${esc(c.id.slice(0,8))}</p></div><span class="status ${c.status}">${statusLabel(c.status)}</span><strong>${money(c.total_minor,c.currency)}</strong><span>↗</span></a>`).join('')||`<div class="empty"><p>${L('Todavía no hay operaciones en esta sesión.','No checkouts in this session yet.')}</p><a class="btn outline" href="/propiedades">${L('Explorar propiedades','Explore properties')}</a></div>`}</div></section>`);if($('#google-login'))$('#google-login').onclick=e=>googleSignIn(e.currentTarget);if($('#logout'))$('#logout').onclick=async()=>{await api('/auth/logout',{method:'POST'});location.reload();};}
async function otherRoute(path){if(path==='/')return home();if(path==='/coleccion')return catalogue();if(path.startsWith('/shop/'))return product(path.split('/')[2]);if(path==='/checkout')return checkout();if(path==='/cuenta')return account();if(path==='/admin')return admin();if(path.startsWith('/pago/')){const id=new URLSearchParams(location.search).get('checkout');if(id)return checkoutResult(id);}if(path==='/privacidad'){frame(`<section class="page-wrap narrow"><p class="kicker">VIICASA</p><h1>${L('Privacidad y condiciones.','Privacy & terms.')}</h1><p class="error">${L('Borrador pendiente de aprobación. No habilitar operaciones públicas antes de completar esta información.','Draft pending approval. Do not enable public checkouts before completing this information.')}</p><h3>${L('Datos de contacto','Contact details')}</h3><p>${L('Los formularios recaban nombre, email y teléfono para atender solicitudes y gestionar operaciones. Falta confirmar responsable, contacto, conservación y procedimiento de derechos.','Forms collect name, email and phone to handle enquiries and checkouts. The controller, contact, retention and rights process must be confirmed.')}</p><h3>${L('Reservaciones y compras','Bookings & purchases')}</h3><p>${L('Revisa las condiciones específicas de la propiedad y el desglose antes de reservar. La política de cancelación, devoluciones, saldo pendiente y entrega deberá aprobarse antes del lanzamiento.','Review property-specific terms and the price breakdown before booking. Cancellation, refunds, balance collection and delivery policies must be approved before launch.')}</p><p>${L('Las cookies de sesión son necesarias para proteger el acceso y conservar el carrito. La preferencia de idioma se guarda en este dispositivo. Al crear una cuenta, guardamos una estimación del país y la zona (Canadá o resto del mundo) a partir de la IP. No guardamos la IP completa para esa clasificación; puede resultar no detectable.','Session cookies protect access and retain the basket. The language preference is stored on this device. When you create an account, we save an IP-based country and region estimate (Canada or rest of the world). We do not store the full IP for this classification; location may be unavailable.')}</p></section>`);return;}throw Error(L('Página no encontrada.','Page not found.'));}

