  try{const summary=await api('/admin/summary');frame(`<section class="admin-layout"><aside class="admin-sidebar"><p class="kicker">VIICASA · ADMIN</p><h2>${L('Todo, en su lugar.','Everything in place.')}</h2><nav>${[['customers','Clientes registrados','Registered customers'],['properties','Propiedades','Properties'],['products','Productos','Products'],['checkouts','Reservaciones y pedidos','Bookings & orders'],['inquiries','Consultas','Enquiries'],['settings','Tienda y entregas','Shop & delivery']].map(([v,es,en])=>`<button data-admin-tab="${v}">${L(es,en)}</button>`).join('')}</nav><a href="/propiedades">${L('Ver sitio','View site')} ↗</a><button class="btn outline small" id="admin-logout">${L('Cerrar sesión','Sign out')}</button></aside><div class="admin-main"><div class="stats-row"><div><span>${L('Propiedades','Properties')}</span><strong>${summary.properties.total}</strong></div><div><span>${L('Productos','Products')}</span><strong>${summary.products.total}</strong></div><div><span>${L('Consultas nuevas','New enquiries')}</span><strong>${summary.inquiries.unread}</strong></div></div><div id="admin-content"></div></div></section>`);document.querySelectorAll('[data-admin-tab]').forEach(b=>b.onclick=()=>adminTab(b.dataset.adminTab).catch(e=>notify(errorText(e))));$('#admin-logout').onclick=async()=>{await api('/auth/logout',{method:'POST'});location.reload();};await adminTab('properties');}
  catch(e){if(![401,403].includes(e.status))throw e;frame(`<section class="page-wrap narrow"><p class="kicker">VIICASA · ADMIN</p><h1>${L('Gestiona tu colección.','Manage your collection.')}</h1><p>${L('Acceso exclusivo para administradores autorizados.','Access for authorised administrators only.')}</p>${settings.demo?`<button class="btn" id="demo-admin">${L('Entrar al administrador de demostración','Open demo administrator')}</button><p class="quiet">${L('Solo disponible en este entorno local aislado. No es un acceso de producción.','Available only in this isolated local environment. Not a production login.')}</p>`:`<a class="btn" href="/cuenta">${L('Iniciar sesión con Google','Sign in with Google')}</a>`}</section>`);if($('#demo-admin'))$('#demo-admin').onclick=async e=>{e.currentTarget.disabled=true;try{await api('/demo-admin',{method:'POST'});await admin();}catch(err){notify(errorText(err));e.currentTarget.disabled=false;}};}
