async function adminTab(tab){
  document.querySelectorAll('[data-admin-tab]').forEach(b=>b.classList.toggle('active',b.dataset.adminTab===tab));const container=$('#admin-content');container.innerHTML=`<p>${L('Cargando…','Loading…')}</p>`;
  if(tab==='customers'){
    const show=async cursor=>{
      const page=await api('/admin/customers?limit=50'+(cursor?'&cursor='+encodeURIComponent(cursor):''));
      container.innerHTML=`<h2>${L('Clientes registrados','Registered customers')}</h2><p class="quiet">${L('Zona estimada por IP al registrarse, no nacionalidad ni domicilio verificado. Los registros anteriores sin información aparecen como “No detectado”.','IP-estimated region at registration, not nationality or verified residence. Older records without location appear as “Not detected”.')}</p><div class="table-scroll"><table><thead><tr><th>${L('Cliente','Customer')}</th><th>${L('Zona de registro','Registration region')}</th><th>${L('Fecha de registro','Registration date')}</th></tr></thead><tbody>${page.items.map(c=>`<tr><td>${esc(c.name)}<small>${esc(c.email)}</small></td><td><span class="status">${regionLabel(c.registration?.region)}</span></td><td>${c.created_at?esc(new Date(c.created_at).toLocaleDateString(lang==='es'?'es-MX':'en-US')):'—'}</td></tr>`).join('')}</tbody></table></div>${!page.items.length?`<p>${L('Todavía no hay clientes registrados. Las visitas anónimas no aparecen en esta lista.','No registered customers yet. Anonymous visits do not appear in this list.')}</p>`:''}<div class="action-row">${cursor?`<button class="btn outline small" id="customers-first">${L('Volver al inicio','Back to first page')}</button>`:''}${page.next_cursor?`<button class="btn small" id="customers-next">${L('Siguiente página','Next page')}</button>`:''}</div>`;
      if($('#customers-first'))$('#customers-first').onclick=()=>show().catch(e=>notify(errorText(e)));
      if($('#customers-next'))$('#customers-next').onclick=()=>show(page.next_cursor).catch(e=>notify(errorText(e)));
    };await show();return;
  }
  if(tab==='properties'||tab==='products'){
    const allItems=await allPages('/admin/'+tab);const items=allItems.filter(p=>!p.archived);container.innerHTML=`<div class="section-title"><h2>${tab==='properties'?L('Propiedades','Properties'):L('Productos','Products')}</h2><button class="btn small" id="add-record">+ ${L('Agregar','Add')}</button></div><div class="admin-records">${items.map(p=>`<article>${photo(p)}<div><h3>${esc(bilingual(p.name))}</h3><p>${esc(p.slug)} · ${p.published&&!p.archived?L('Publicada','Published'):p.archived?L('Archivada','Archived'):L('Borrador','Draft')}</p></div><div class="admin-record-actions"><button class="btn outline small" data-edit="${p.id}">${L('Editar','Edit')}</button>${tab==='properties'?`<button class="btn outline small" data-calendar="${p.id}" aria-label="${L('Ver calendario de','View calendar for')} ${esc(p.name)}">${icon('calendar')}</button>`:`<button class="btn outline small" data-variants="${p.id}">${L('Inventario','Inventory')}</button>`}</div></article>`).join('')||`<p>${L('Sin registros. Agrega el primero.','No records yet. Add the first one.')}</p>`}</div>`;$('#add-record').onclick=()=>editRecord(tab);document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editRecord(tab,b.dataset.edit).catch(e=>notify(errorText(e))));document.querySelectorAll('[data-calendar]').forEach(b=>b.onclick=()=>calendarView(b.dataset.calendar).catch(e=>notify(errorText(e))));document.querySelectorAll('[data-variants]').forEach(b=>b.onclick=()=>variantsView(b.dataset.variants).catch(e=>notify(errorText(e))));return;
  }
  if(tab==='checkouts'||tab==='inquiries'){
    const rows=await allPages('/admin/'+tab);container.innerHTML=`<div class="section-title"><h2>${tab==='checkouts'?L('Operaciones','Checkouts'):L('Consultas','Enquiries')}</h2></div><div class="table-scroll"><table><thead><tr><th>${L('Cliente','Customer')}</th><th>${L('Detalle','Detail')}</th><th>${L('Estado','Status')}</th><th>${L('Acciones','Actions')}</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.customer_name||r.name)}<small>${esc(r.customer_email||r.email)}</small><small>${esc(r.customer_phone||r.phone)}</small></td><td>${tab==='checkouts'?esc(r.detail.property_name||'ViiShop')+'<small>'+money(r.total_minor,r.currency)+'</small>':esc(r.message)}<small>${new Date(r.created_at).toLocaleDateString(lang==='es'?'es-MX':'en-US')}</small></td><td><span class="status ${r.status}">${statusLabel(r.status)}</span></td><td>${tab==='inquiries'?`<select data-inquiry="${r.id}">${['new','attended','archived'].map(v=>`<option value="${v}" ${v===r.status?'selected':''}>${statusLabel(v)}</option>`).join('')}</select>`:`<button class="btn outline small" data-operation="${r.id}">${L('Ver','View')}</button>`}</td></tr>`).join('')}</tbody></table></div>${!rows.length?`<p>${L('Todavía no hay registros.','No records yet.')}</p>`:''}`;document.querySelectorAll('[data-inquiry]').forEach(s=>s.onchange=async()=>{try{await api('/admin/inquiries/'+s.dataset.inquiry,{method:'PATCH',body:{status:s.value}});notify(L('Estado actualizado.','Status updated.'));}catch(e){notify(errorText(e));}});document.querySelectorAll('[data-operation]').forEach(b=>b.onclick=()=>adminOperation(b.dataset.operation).catch(e=>notify(errorText(e))));return;
  }
  const data=(await api('/shop/settings')).items;container.innerHTML=`<h2>${L('Tienda y entregas','Shop & delivery')}</h2>${data.map(s=>`<form class="settings-form" data-currency="${s.currency}"><h3>${s.currency}</h3><label class="consent"><input type="checkbox" name="pickup_enabled" ${s.pickup_enabled?'checked':''}>${L('Permitir recolección','Allow pickup')}</label><label class="consent"><input type="checkbox" name="shipping_enabled" ${s.shipping_enabled?'checked':''}>${L('Permitir envío','Allow shipping')}</label><label>${L('Tarifa de envío','Shipping fee')}<input type="number" min="0" step=".01" name="shipping" value="${s.shipping_minor/100}" required></label><label>${L('Instrucciones de recolección','Pickup instructions')}<textarea name="pickup_instructions">${esc(s.pickup_instructions)}</textarea></label><label>${L('Condiciones','Terms')}<textarea name="terms">${esc(s.terms)}</textarea></label><button class="btn">${L('Guardar','Save')}</button></form>`).join('')}`;document.querySelectorAll('.settings-form').forEach(f=>f.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f));try{await api('/admin/shop/settings/'+f.dataset.currency,{method:'PUT',body:{pickup_enabled:d.pickup_enabled==='on',shipping_enabled:d.shipping_enabled==='on',shipping_minor:Math.round(Number(d.shipping)*100),pickup_instructions:d.pickup_instructions,terms:d.terms}});notify(L('Configuración guardada.','Settings saved.'));}catch(err){notify(errorText(err));}});
}
function field(name,label,value='',type='text',extra=''){return `<label>${label}<input type="${type}" name="${name}" value="${esc(value)}" ${extra}></label>`;}
async function editRecord(kind,id){
  const property=kind==='properties',p=id?await api('/admin/'+kind+'/'+id):{images:[],published:false,currency:'USD',timezone:'America/Mexico_City',capacity:2,bedrooms:1,bathrooms:1,min_nights:2,deposit_percent:30,nightly_minor:0,cleaning_minor:0,amenities:[]};let images=[...p.images];const [es='',en='']=String(p.description||'').split('\n[EN]\n'),[policyEs='',policyEn='']=String(p.policies||'').split('\n[EN]\n');
  modal(property?L('Editar propiedad','Edit property'):L('Editar producto','Edit product'),`<form id="editor-form"><div class="form-pair">${field('name',L('Nombre','Name'),p.name,'text','required maxlength="200"')}${field('slug',L('Dirección de la página (slug)','Page address (slug)'),p.slug,'text','required pattern="[a-z0-9]+(-[a-z0-9]+)*" maxlength="100"')}</div><p class="quiet">${property?'/viiconcierge/':'/shop/'}<span id="slug-preview">${esc(p.slug||'mi-propiedad')}</span></p><div class="form-pair"><label>${L('Descripción en español','Spanish description')}<textarea name="description_es" maxlength="4500" required>${esc(es)}</textarea></label><label>${L('Descripción en inglés','English description')}<textarea name="description_en" maxlength="4500" required>${esc(en)}</textarea></label></div>${property?`<div class="form-pair">${field('location',L('Ubicación (ES / EN)','Location (ES / EN)'),p.location,'text','required')}${field('timezone',L('Zona horaria','Time zone'),p.timezone,'text','required')}</div><div class="form-grid">${[['capacity','Huéspedes','Guests',1],['bedrooms','Recámaras','Bedrooms',0],['bathrooms','Baños','Bathrooms',0],['min_nights','Noches mínimas','Minimum nights',1],['deposit_percent','Anticipo (%)','Deposit (%)',1]].map(([n,es,en,min])=>field(n,L(es,en),p[n],'number',`required min="${min}" max="${n==='min_nights'?90:100}"`)).join('')}</div><div class="form-grid">${field('nightly',L('Tarifa por noche','Nightly rate'),p.nightly_minor/100,'number','required min=".01" step=".01"')}${field('cleaning',L('Limpieza','Cleaning'),p.cleaning_minor/100,'number','required min="0" step=".01"')}<label>${L('Moneda','Currency')}<select name="currency"><option ${p.currency==='MXN'?'selected':''}>MXN</option><option ${p.currency==='USD'?'selected':''}>USD</option><option ${p.currency==='CAD'?'selected':''}>CAD</option></select></label></div><label>${L('Amenidades: una por línea, Español / Inglés','Amenities: one per line, Spanish / English')}<textarea name="amenities" maxlength="4000">${esc(p.amenities.join('\n'))}</textarea></label><div class="form-pair"><label>${L('Condiciones en español','Spanish policies')}<textarea name="policies_es" maxlength="2300" required>${esc(policyEs)}</textarea></label><label>${L('Condiciones en inglés','English policies')}<textarea name="policies_en" maxlength="2300" required>${esc(policyEn)}</textarea></label></div>`:field('category',L('Categoría (ES / EN)','Category (ES / EN)'),p.category,'text','required maxlength="80"')}${property?rateFields(p,L):''}<div class="photo-editor"><h3>${L('Imagen principal y galería','Cover image & gallery')}</h3><p class="quiet">${L('La primera fotografía será la imagen principal. Puedes elegir otra con “Principal”. PNG, JPEG, WebP o GIF; hasta 8 MB.','The first photograph is the cover. Choose another with “Cover”. PNG, JPEG, WebP or GIF; up to 8 MB.')}</p><input id="photo-upload" type="file" accept="image/png,image/jpeg,image/webp,image/gif" multiple><p id="upload-status" role="status"></p><div id="photo-editor-grid"></div></div><label class="consent"><input type="checkbox" name="published" ${p.published?'checked':''}>${L('Publicar en el sitio','Publish on the website')}</label><p class="form-message error" hidden role="alert"></p><div class="action-row"><button class="btn">${L('Guardar cambios','Save changes')}</button>${id&&!p.archived?`<button type="button" class="btn outline" id="archive-record">${L('Archivar','Archive')}</button>`:''}</div></form>`);
  const f=$('#editor-form');if(property)bindPrimaryCurrency(f);let customSlug=!!id;f.elements.slug.oninput=()=>{customSlug=true;$('#slug-preview').textContent=f.elements.slug.value;};f.elements.name.oninput=()=>{if(!customSlug){f.elements.slug.value=f.elements.name.value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,100);$('#slug-preview').textContent=f.elements.slug.value;}};
  const draw=()=>{$('#photo-editor-grid').innerHTML=images.map((im,i)=>`<div><img src="${esc(imageUrl(im))}" alt="${L('Foto','Photo')} ${i+1}"><button type="button" data-cover="${i}">${i===0?L('✓ Principal','✓ Cover'):L('Hacer principal','Set cover')}</button><button type="button" data-remove-photo="${i}">${L('Quitar','Remove')}</button></div>`).join('');document.querySelectorAll('[data-cover]').forEach(b=>b.onclick=()=>{images.unshift(images.splice(Number(b.dataset.cover),1)[0]);draw();});document.querySelectorAll('[data-remove-photo]').forEach(b=>b.onclick=()=>{images.splice(Number(b.dataset.removePhoto),1);draw();});};draw();
  $('#photo-upload').onchange=async e=>{const files=[...e.target.files],submit=f.querySelector('button[type="submit"]')||f.querySelector('.action-row .btn');submit.disabled=true;try{for(const file of files){if(images.length>=30)throw Error(L('Máximo 30 imágenes.','Maximum 30 images.'));if(file.size>8*1024*1024)throw Error(L('La imagen supera 8 MB.','Image exceeds 8 MB.'));const fd=new FormData();fd.append('file',file);$('#upload-status').textContent=L('Subiendo…','Uploading…');const r=await api('/admin/media',{method:'POST',body:fd});images.push(r.url);draw();}$('#upload-status').textContent=L('Fotografías cargadas. Guarda la propiedad para aplicar los cambios.','Photos uploaded. Save the record to apply changes.');}catch(err){$('#upload-status').textContent=errorText(err);}finally{submit.disabled=false;e.target.value='';}};
  f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('.action-row .btn');b.disabled=true;const d=Object.fromEntries(new FormData(f));const common={name:d.name,slug:d.slug,description:d.description_es+'\n[EN]\n'+d.description_en,images,published:d.published==='on'};const body=property?{...common,location:d.location,timezone:d.timezone,capacity:Number(d.capacity),bedrooms:Number(d.bedrooms),bathrooms:Number(d.bathrooms),min_nights:Number(d.min_nights),deposit_percent:Number(d.deposit_percent),nightly_minor:Math.round(Number(d.nightly)*100),cleaning_minor:Math.round(Number(d.cleaning)*100),currency:d.currency,rates:readRates(d),amenities:d.amenities.split('\n').map(s=>s.trim()).filter(Boolean),policies:d.policies_es+'\n[EN]\n'+d.policies_en}:{...common,category:d.category};try{const saved=await api('/admin/'+kind+(id?'/'+id:''),{method:id?'PUT':'POST',body});$('#detail').close();await adminTab(kind);notify(L('Cambios guardados.','Changes saved.'));if(!property&&!id)await variantsView(saved.id);}catch(err){const m=f.querySelector('.form-message');m.hidden=false;m.textContent=errorText(err);b.disabled=false;}};
  if($('#archive-record'))$('#archive-record').onclick=()=>{if(!confirm(L('¿Archivar esta publicación? Se conservará su historial.','Archive this listing? Its history will be retained.')))return;api('/admin/'+kind+'/'+id,{method:'DELETE'}).then(async()=>{$('#detail').close();await adminTab(kind);}).catch(e=>notify(errorText(e)));};
}
async function calendarView(id){
  const from=today(),to=new Date(Date.now()+180*86400000).toISOString().slice(0,10),c=await api('/admin/properties/'+id+'/calendar?'+new URLSearchParams({from,to}));modal(L('Disponibilidad de la propiedad','Property availability'),`<p class="quiet">${from} → ${to}</p><div class="calendar-records">${[...c.blocks.map(b=>({...b,block:true})),...c.bookings].map(b=>`<p>${b.check_in} → ${b.check_out} <span class="tag">${b.block?L('Bloqueo','Blocked'):statusLabel(b.status)}</span>${b.block?`<button data-unblock="${b.id}" class="btn outline small">${L('Liberar','Release')}</button>`:''}</p>`).join('')||`<p>${L('Sin bloqueos ni reservas en este período.','No holds or bookings in this period.')}</p>`}</div><h3>${L('Bloquear fechas','Block dates')}</h3><form id="block-form"><div class="form-pair">${field('check_in',L('Desde','From'),from,'date','required')}${field('check_out',L('Hasta (salida)','Until (checkout)'),from,'date','required')}</div>${field('reason',L('Motivo','Reason'),'','text','required maxlength="300"')}<button class="btn">${L('Bloquear período','Block period')}</button><p class="form-message" role="status"></p></form>`);$('#block-form').onsubmit=async e=>{e.preventDefault();try{await api('/admin/properties/'+id+'/calendar-blocks',{method:'POST',body:Object.fromEntries(new FormData(e.currentTarget))});$('#detail').close();await calendarView(id);}catch(err){$('#block-form .form-message').textContent=errorText(err);}};document.querySelectorAll('[data-unblock]').forEach(b=>b.onclick=async()=>{try{await api('/admin/calendar-blocks/'+b.dataset.unblock,{method:'DELETE'});$('#detail').close();await calendarView(id);}catch(e){notify(errorText(e));}});
}
async function variantsView(id){const p=await api('/admin/products/'+id);modal(L('Inventario y variantes','Inventory & variants'),`<h3>${esc(bilingual(p.name))}</h3>${p.variants.map(v=>`<div class="variant-row"><strong>${esc(v.name)}</strong><span>${money(v.price_minor,v.currency)} · ${v.stock} ${L('unidades','units')}</span><button class="btn outline small" data-stock="${v.id}">${L('Ajustar','Adjust')}</button></div>`).join('')}<h3>${L('Agregar variante','Add variant')}</h3><form id="variant-form"><div class="form-pair">${field('name',L('Nombre','Name'),'','text','required')}${field('sku','SKU','','text','required')}</div><div class="form-grid">${field('price',L('Precio','Price'),'','number','required min=".01" step=".01"')}${field('stock',L('Existencias','Stock'),0,'number','required min="0"')}<label>${L('Moneda','Currency')}<select name="currency"><option>USD</option><option>CAD</option><option>MXN</option></select></label></div>${priceFields({},L)}<button class="btn">${L('Agregar','Add')}</button><p class="form-message" role="status"></p></form>`);bindPrimaryCurrency($('#variant-form'));$('#variant-form').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));try{await api('/admin/products/'+id+'/variants',{method:'POST',body:{sku:d.sku,name:d.name,price_minor:Math.round(Number(d.price)*100),currency:d.currency,prices:readPrices(d),stock:Number(d.stock),active:true}});$('#detail').close();await variantsView(id);}catch(err){$('#variant-form .form-message').textContent=errorText(err);}};document.querySelectorAll('[data-stock]').forEach(b=>b.onclick=()=>{const v=p.variants.find(x=>x.id===b.dataset.stock);$('#detail').close();modal(L('Ajustar variante','Adjust variant'),`<form id="stock-form">${field('name',L('Nombre','Name'),v.name,'text','required')}${field('price',L('Precio','Price'),v.price_minor/100,'number','required min=".01" step=".01"')}${priceFields(v,L)}${field('delta',L('Cambio de stock (+/-)','Stock adjustment (+/-)'),0,'number','required')}${field('reason',L('Motivo','Reason'),'','text','required')}<label class="consent"><input name="active" type="checkbox" ${v.active?'checked':''}>${L('Activa','Active')}</label><button class="btn">${L('Guardar','Save')}</button><p class="form-message" role="status"></p></form>`);bindPrimaryCurrency($('#stock-form'),v.currency);$('#stock-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,d=Object.fromEntries(new FormData(f));try{await api('/admin/variants/'+v.id,{method:'PUT',body:{sku:v.sku,name:d.name,price_minor:Math.round(Number(d.price)*100),currency:v.currency,prices:readPrices(d),active:d.active==='on'}});if(Number(d.delta))await api('/admin/variants/'+v.id+'/stock',{method:'POST',body:{delta:Number(d.delta),reason:d.reason}});$('#detail').close();await variantsView(id);}catch(err){f.querySelector('.form-message').textContent=errorText(err);}};});}
async function adminOperation(id){const c=await api('/admin/checkouts/'+id);modal(L('Detalle de operación','Checkout details'),`<p>${esc(c.id)}</p><span class="status ${c.status}">${statusLabel(c.status)}</span><h3>${esc(c.detail.property_name||'ViiShop')}</h3><p>${esc(c.customer_name)} · ${esc(c.customer_email)}</p><p>${esc(c.customer_phone)}</p>${c.kind==='booking'?`<p>${c.detail.check_in} → ${c.detail.check_out} · ${c.detail.guests} ${L('huéspedes','guests')}</p>`:c.detail.items.map(x=>`<p>${esc(bilingual(x.name))} × ${x.quantity}</p>`).join('')}<p>${L('Total','Total')}: ${money(c.total_minor,c.currency)}</p><p>${L('A pagar','Due')}: ${money(c.due_minor,c.currency)}</p>${settings.demo&&c.status==='pending'&&c.payment?.provider==='demo'?`<button class="btn" id="simulate-payment">${L('Simular pago aprobado (sin cobro)','Simulate approved payment (no charge)')}</button>`:''}${c.status==='pending'?`<button class="btn outline" id="admin-cancel">${L('Cancelar pendiente','Cancel pending checkout')}</button>`:''}<p class="form-message" role="status"></p>`);if($('#simulate-payment'))$('#simulate-payment').onclick=async()=>{try{await api('/admin/payments/'+c.payment.id+'/simulate',{method:'POST',body:{event_id:crypto.randomUUID(),outcome:'paid'}});$('#detail').close();await adminTab('checkouts');}catch(e){$('.form-message').textContent=errorText(e);}};if($('#admin-cancel'))$('#admin-cancel').onclick=async()=>{if(!confirm(L('¿Cancelar la operación pendiente?','Cancel this pending checkout?')))return;try{await api('/admin/checkouts/'+id+'/cancel',{method:'POST'});$('#detail').close();await adminTab('checkouts');}catch(e){$('.form-message').textContent=errorText(e);}};}

start();
